/**
 * CG-07 (G-A3) "Try another look": a whole-site layout reshuffle.
 * CG-14 (G-SGE-4) "New layout" on one section: the same free reseed, scoped.
 *
 * Plain sections pick one of their layout variants from a seed (#522). This
 * keeps the owner's words, photos, colours and pages and only changes the
 * seed: look 0 is the original (the slug alone), look N mixes `#look-N` into
 * it. A per-section override mixes `#sec-<id>-N` on top. Numbers live in
 * website_settings.generation (look + sectionLooks), so no migration is needed
 * and nothing is regenerated by AI (no build cost). Sections with their own
 * AI composition are not touched.
 */

export const MAX_LOOKS = 12;

type Generation = Record<string, unknown> | null | undefined;

/** The saved look number, 0 (original) when missing or invalid. */
export function readSiteLook(generation: unknown): number {
  const raw = generation && typeof generation === "object" ? (generation as Record<string, unknown>)["look"] : undefined;
  return cleanLook(raw);
}

export function cleanLook(raw: unknown): number {
  const n = typeof raw === "string" && raw.trim() !== "" ? Number(raw) : raw;
  return typeof n === "number" && Number.isInteger(n) && n >= 0 && n < MAX_LOOKS ? n : 0;
}

/** Per-section look overrides keyed by section id. Missing / invalid → look 0. */
export function readSectionLooks(generation: unknown): Record<string, number> {
  const raw = generation && typeof generation === "object" ? (generation as Record<string, unknown>)["sectionLooks"] : undefined;
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return {};
  const out: Record<string, number> = {};
  for (const [id, value] of Object.entries(raw as Record<string, unknown>)) {
    if (typeof id !== "string" || !id.trim()) continue;
    const look = cleanLook(value);
    if (look > 0) out[id] = look;
  }
  return out;
}

export function readSectionLook(generation: unknown, sectionId: string): number {
  if (!sectionId.trim()) return 0;
  return readSectionLooks(generation)[sectionId] ?? 0;
}

/** The variant seed for a look. Look 0 is exactly the pre-CG-07 seed, so existing sites don't change. */
export function lookSeed(slug: string | null | undefined, look: number): string | null {
  const base = typeof slug === "string" ? slug.trim() : "";
  if (!base) return null;
  return look > 0 ? `${base}#look-${look}` : base;
}

/**
 * Seed for one section: site look, then an optional per-section override.
 * Look 0 on the section keeps the site seed alone so untouched sections stay put.
 */
export function sectionLookSeed(
  slug: string | null | undefined,
  siteLook: number,
  sectionId: string,
  sectionLook: number,
): string | null {
  const base = lookSeed(slug, siteLook);
  if (!base) return null;
  const id = sectionId.trim();
  const look = cleanLook(sectionLook);
  if (!id || look === 0) return base;
  return `${base}#sec-${id}-${look}`;
}

/** Seed for one section read straight from generation. */
export function seedForSection(slug: string | null | undefined, generation: unknown, sectionId: string): string | null {
  return sectionLookSeed(slug, readSiteLook(generation), sectionId, readSectionLook(generation, sectionId));
}

/** The next look to preview after `from` (wraps, never returns `from`). */
export function nextLook(from: number): number {
  return (cleanLook(from) + 1) % MAX_LOOKS;
}

/** A copy of the site whose generation carries `look`, for previewing without saving. */
export function withLook<T extends { settings?: { generation?: unknown } | null }>(site: T, look: number): T {
  const generation = (site.settings?.generation ?? {}) as Generation;
  return { ...site, settings: { ...(site.settings ?? {}), generation: { ...(generation ?? {}), look: cleanLook(look) } } };
}

/** A copy of the site with one section's look overridden, for previewing without saving. */
export function withSectionLook<T extends { settings?: { generation?: unknown } | null }>(site: T, sectionId: string, look: number): T {
  const id = sectionId.trim();
  if (!id) return site;
  const generation = { ...((site.settings?.generation ?? {}) as Record<string, unknown>) };
  const sectionLooks = { ...readSectionLooks(generation) };
  const cleaned = cleanLook(look);
  if (cleaned === 0) delete sectionLooks[id];
  else sectionLooks[id] = cleaned;
  if (Object.keys(sectionLooks).length === 0) delete generation["sectionLooks"];
  else generation["sectionLooks"] = sectionLooks;
  return { ...site, settings: { ...(site.settings ?? {}), generation } };
}

/** True when at least one section is plain (no AI composition), i.e. a new look will visibly change something. */
export function lookCanChange(sections: unknown, hasComposition: (settings: unknown) => boolean): boolean {
  if (!Array.isArray(sections)) return false;
  return sections.some((s) => s && typeof s === "object" && !hasComposition((s as { settings?: unknown }).settings));
}

/** True when this one section can take a free layout reseed (plain, no AI composition). */
export function sectionCanReseed(settings: unknown, hasComposition: (settings: unknown) => boolean): boolean {
  return !hasComposition(settings);
}
